diff --git a/js/piwik.js b/js/piwik.js
index e9b8c1ffdaad..78b5d80c99f4 100644
--- a/js/piwik.js
+++ b/js/piwik.js
@@ -4023,9 +4023,13 @@ if (typeof window.Piwik !== 'object') {
                     if (isFunction(windowAlias.GearsFactory)) {
