From 95e08807be5642e4fc857a0fc1bb0865e53d8b6a Mon Sep 17 00:00:00 2001
From: Thomas Steur <tsteur@users.noreply.github.com>
Date: Sun, 28 Jun 2020 11:50:22 +1200
Subject: [PATCH 13/20] send tracking request if needed when enable cookies

---
 core/Archive/ArchiveInvalidator.php | 13 +++++++++----
 js/piwik.js                         | 21 +++++++++++++++++++--
 2 files changed, 28 insertions(+), 6 deletions(-)

diff --git a/core/Archive/ArchiveInvalidator.php b/core/Archive/ArchiveInvalidator.php
index ad449921f218..5350737d7dbb 100644
--- a/core/Archive/ArchiveInvalidator.php
+++ b/core/Archive/ArchiveInvalidator.php
@@ -78,7 +78,7 @@ public function getAllRememberToInvalidateArchivedReportsLater()
         // we do not really have to get the value first. we could simply always try to call set() and it would update or
         // insert the record if needed but we do not want to lock the table (especially since there are still some
         // MyISAM installations)
-        $values = Option::getLike('%' . $this->rememberArchivedReportIdStart . '%');
+        $values = Option::getLike('%' . $this->replaceUnderscore($this->rememberArchivedReportIdStart) . '%');

         $all = [];
         foreach ($values as $name => $value) {
@@ -103,7 +103,7 @@ public function rememberToInvalidateArchivedReportsLater($idSite, Date $date)
             // we do not really have to get the value first. we could simply always try to call set() and it would update or
             // insert the record if needed but we do not want to lock the table (especially since there are still some
             // MyISAM installations)
-            $value = Option::getLike('%' . $key . '%');
+            $value = Option::getLike('%' . $this->replaceUnderscore($key) . '%');
         }

         // getLike() returns an empty array rather than 'false'
@@ -122,6 +122,11 @@ public function rememberToInvalidateArchivedReportsLater($idSite, Date $date)
         }
     }

+    private function replaceUnderscore($key)
+    {
+        return str_replace('_', '\_', $key);
+    }
+
     private function getRememberedArchivedReportsOptionFromTracker($idSite, $dateStr)
     {
         $cacheKey = self::TRACKER_CACHE_KEY;
@@ -136,7 +141,7 @@ private function getRememberedArchivedReportsOptionFromTracker($idSite, $dateStr

     public function getRememberedArchivedReportsThatShouldBeInvalidated()
     {
-        $reports = Option::getLike('%' . $this->rememberArchivedReportIdStart . '%_%');
+        $reports = Option::getLike('%' . $this->replaceUnderscore($this->rememberArchivedReportIdStart) . '%\_%');

         $sitesPerDay = array();

@@ -210,7 +215,7 @@ private function deleteOptionLike($id)
     {
         // we're not using deleteLike since it maybe could cause deadlocks see https://github.com/matomo-org/matomo/issues/15545
         // we want to reduce number of rows scanned and only delete specific primary key
-        $keys = Option::getLike('%' . $id . '%');
+        $keys = Option::getLike('%' . $this->replaceUnderscore($id) . '%');

         if (empty($keys)) {
             return;
diff --git a/js/piwik.js b/js/piwik.js
index 12855093874b..88ed7d64013c 100644
--- a/js/piwik.js
+++ b/js/piwik.js
@@ -3261,7 +3261,10 @@ if (typeof window.Piwik !== 'object') {
                 consentRequestsQueue = [],

                 // a unique ID for this tracker during this request
-                uniqueTrackerId = trackerIdCounter++;
+                uniqueTrackerId = trackerIdCounter++,
+
+                // whether a tracking request has been sent yet during this page view
+                hasSentTrackingRequestYet = false;

             // Document title
             try {
@@ -3843,6 +3846,9 @@ if (typeof window.Piwik !== 'object') {
                     consentRequestsQueue.push(request);
                     return;
                 }
+
+                hasSentTrackingRequestYet = true;
+
                 if (!configDoNotTrack && request) {
                     if (configConsentRequired && configHasConsent) { // send a consent=1 when explicit consent is given for the apache logs
                         request += '&consent=1';
@@ -3909,6 +3915,8 @@ if (typeof window.Piwik !== 'object') {
                     return;
                 }

+                hasSentTrackingRequestYet = true;
+
                 makeSureThereIsAGapAfterFirstTrackingRequestToPreventMultipleVisitorCreation(function () {
                     var chunks = arrayChunk(requests, 50);

@@ -6803,7 +6811,16 @@ if (typeof window.Piwik !== 'object') {
                     configCookiesDisabled = false;
                     if (configTrackerSiteId) {
                         setVisitorIdCookie();
-                        getRequest('ping=1'); // sets attribution cookie, we don't actually send the request
+                        if (hasSentTrackingRequestYet) {
+                            // sets attribution cookie, we don't actually send the request
+                            // we assume in this case there might not be a following tracking request so we trigger one
+                            // ourselves to ensure also that in the backend the visitorId for this fingerprint will be
+                            // set... otherwise if no tracking request follows, it would never be updated and this visit
+                            // would not be linked to this visitor. If no tracking request was sent yet we assume one will
+                            // follow. We don't use the ping tracking method as it might be queued... send it directly...
+                            var request = getRequest('ping=1', null, 'ping');
+                            sendRequest(request, configTrackerPause);
+                        }
                     }
                 }
             };

